contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient balance for put");

        (uint initUnlock, uint initBalance) = c.Acc(address(this));
        uint initCBal = address(c).balance;

        c.Put{value: putAmount}(unlockTime);

        (uint afterPutUnlock, uint afterPutBalance) = c.Acc(address(this));
        uint afterPutCBal = address(c).balance;

        // Put must credit exactly the sent amount and only move the lock forward
        bool putOk = afterPutBalance == initBalance + putAmount
                  && afterPutCBal == initCBal + putAmount
                  && afterPutUnlock >= initUnlock
                  && afterPutUnlock >= block.timestamp;

        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        (uint afterCollectUnlock, uint afterCollectBalance) = c.Acc(address(this));
        uint afterCollectCBal = address(c).balance;

        // Collect may only either do nothing (revert) or, if it succeeds, reduce
        // the recorded balance and the contract Ether by exactly the collected amount.
        bool collectOk;
        if (collectReverted) {
            collectOk = afterCollectBalance == afterPutBalance
                     && afterCollectCBal == afterPutCBal
                     && afterCollectUnlock == afterPutUnlock;
        } else {
            collectOk = afterCollectBalance == afterPutBalance - collectAmount
                     && afterCollectCBal == afterPutCBal - collectAmount
                     && afterCollectUnlock == afterPutUnlock;
        }

        assert(putOk && collectOk);
    }

    receive() external payable {}
}

